#include "stdlib/lapack/base/dgttrf.h"
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define NAME "dgttrf"
#define REPEATS 3
#define ITERATIONS 10000

/**
* Runs a tridiagonal factorization benchmark.
*
* @param N       matrix order
* @return        elapsed time in seconds
*/
static double benchmark( const LAPACK_INT N ) {
	double *DL;
	double *D;
	double *DU;
	double *DU2;
	LAPACK_INT *IPIV;
	LAPACK_INT info;
	LAPACK_INT i;
	LAPACK_INT j;
	clock_t t;

	DL = (double *)malloc( N*sizeof( double ) );
	D = (double *)malloc( N*sizeof( double ) );
	DU = (double *)malloc( N*sizeof( double ) );
	DU2 = (double *)malloc( N*sizeof( double ) );
	IPIV = (LAPACK_INT *)malloc( N*sizeof( LAPACK_INT ) );
	if ( DL == NULL || D == NULL || DU == NULL || DU2 == NULL || IPIV == NULL ) {
		free( DL ); free( D ); free( DU ); free( DU2 ); free( IPIV );
		exit( 1 );
	}
	t = clock();
	for ( i = 0; i < ITERATIONS; i++ ) {
		for ( j = 0; j < N; j++ ) {
			DL[ j ] = 1.0;
			D[ j ] = 4.0;
			DU[ j ] = 1.0;
		}
		info = API_SUFFIX(c_dgttrf)( N, DL, D, DU, DU2, IPIV );
		if ( info != 0 || D[ N-1 ] <= 0.0 ) {
			free( DL ); free( D ); free( DU ); free( DU2 ); free( IPIV );
			exit( 1 );
		}
	}
	t = clock() - t;
	free( DL ); free( D ); free( DU ); free( DU2 ); free( IPIV );
	return (double)t / CLOCKS_PER_SEC;
}

int main( void ) {
	const LAPACK_INT orders[] = { 4, 16, 256 };
	double elapsed;
	int count;
	int i;
	int j;

	printf( "TAP version 13\n" );
	count = 0;
	for ( i = 0; i < 3; i++ ) {
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			elapsed = benchmark( orders[ i ] );
			printf( "# c::%s:N=%" LAPACK_IFMT "\n", NAME, orders[ i ] );
			printf( "  ---\n  iterations: %d\n  elapsed: %0.9f\n  rate: %0.9f\n  ...\n", ITERATIONS, elapsed, ITERATIONS/elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	printf( "1..%d\n# total %d\n# pass %d\n# ok\n", count, count, count );
	return 0;
}
